llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a lipophilic drug with extensive first-pass metabolism, had a mean systemic availability of 16.5% in healthy volunteers after oral administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine oral bioavailability was 0.18 in normal subjects, below the 20% threshold, consistent with low systemic availability for a lipophilic, high-first-pass drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Nifedipine oral bioavailability was reported as 40–50% in humans, above the threshold, but this reflects a dihydropyridine with near-complete absorption and is not structurally transferable to the query polyprenyl quinone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C42"],
      "claim": "Methocarbamol oral bioavailability was 90% in humans, above the threshold, but this small soluble carbamate is not a relevant structural or physicochemical analog for the highly lipophilic query molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10 (ubiquinone-10), a very lipophilic high-molecular-weight benzoquinone with poor aqueous solubility. No direct F record is present, and the closest lipophilic high-first-pass comparators fall below 20%; recognized CoQ10 oral absorption is poor, so the prediction is low.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability value for coenzyme Q10 in the evidence set.",
    "No structurally close polyprenyl quinone comparator is available.",
    "Formulation and food effects on CoQ10 absorption are not captured by the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

